//
//  Profile.swift
//  Replog
//
//  Single-row user profile & app settings. Stored in SwiftData and fetched-or-created
//  via the helpers in ModelContainer+Replog.
//

import Foundation
import SwiftData

/// The user's training goal from onboarding.
enum Goal: String, Codable, CaseIterable, Identifiable, Sendable {
    case buildMuscle, loseWeight, recomp, sport
    var id: String { rawValue }
    var displayName: String {
        switch self {
        case .buildMuscle: return "Build muscle"
        case .loseWeight:  return "Lose weight"
        case .recomp:      return "Build muscle & lose fat"
        case .sport:       return "Train for a sport"
        }
    }
    /// Short label for chips / the Profile header.
    var shortName: String {
        switch self {
        case .buildMuscle: return "Hypertrophy"
        case .loseWeight:  return "Fat loss"
        case .recomp:      return "Recomposition"
        case .sport:       return "Sport"
        }
    }
}

/// Display unit for weights. Storage is always kg.
enum Units: String, Codable, CaseIterable, Identifiable, Sendable {
    case kg, lb
    var id: String { rawValue }
    var label: String { rawValue }
}

@Model
final class UserProfile {
    /// The user's full name ("First Last"), captured during onboarding.
    var name: String = ""
    var goalRaw: String = Goal.buildMuscle.rawValue
    /// Consecutive scheduled workouts completed (see `StreakEngine.workoutStreak`).
    var streak: Int = 0
    /// Consecutive "perfect weeks" (see `StreakEngine.weekStreak`).
    var weekStreak: Int = 0
    var doneDates: [Date] = []
    var onboardingDone: Bool = false
    var totalWorkouts: Int = 0

    init(name: String = "", goal: Goal = .buildMuscle) {
        self.name = name
        self.goalRaw = goal.rawValue
    }

    var goal: Goal {
        get { Goal(rawValue: goalRaw) ?? .buildMuscle }
        set { goalRaw = newValue.rawValue }
    }

    /// The consecutive-workout streak (alias for `streak`, for readable call sites).
    var workoutStreak: Int {
        get { streak }
        set { streak = newValue }
    }

    /// First name for greetings, falling back to a friendly default.
    var firstName: String {
        let first = name.split(separator: " ").first.map(String.init) ?? name
        return first.isEmpty ? "there" : first
    }

    /// The user's initial for the avatar.
    var initial: String {
        let trimmed = name.trimmingCharacters(in: .whitespaces)
        return trimmed.isEmpty ? "?" : String(trimmed.prefix(1)).uppercased()
    }
}

@Model
final class AppSettings {
    var unitsRaw: String = Units.kg.rawValue
    var darkMode: Bool = false
    var restTimerAuto: Bool = false
    var restSeconds: Int = 90

    init() {}

    var units: Units {
        get { Units(rawValue: unitsRaw) ?? .kg }
        set { unitsRaw = newValue.rawValue }
    }
}

//
//  Session.swift
//  Replog
//
//  Live workout logging models. An ActiveSession is created from a Workout's
//  prescribed sets and persisted so an in-progress workout survives relaunch.
//

import Foundation
import SwiftData

@Model
final class ActiveSession {
    var id: UUID = UUID()
    var workoutId: UUID?
    var name: String = ""
    var planName: String = ""
    var startedAt: Date = Date()
    /// Whether the live session is currently presented. Closing with "X" sets this
    /// false (paused & persisted) so the workout survives and can be continued; it is
    /// only deleted on Finish.
    var isOpen: Bool = true

    @Relationship(deleteRule: .cascade, inverse: \SessionExercise.session)
    var exercises: [SessionExercise] = []

    init(workoutId: UUID?, name: String, planName: String, startedAt: Date = Date()) {
        self.workoutId = workoutId
        self.name = name
        self.planName = planName
        self.startedAt = startedAt
    }

    /// Exercises ordered with finished ones (positive doneOrder) pushed to the bottom.
    var orderedExercises: [SessionExercise] {
        exercises.sorted { a, b in
            switch (a.isDone, b.isDone) {
            case (false, true): return true
            case (true, false): return false
            case (true, true):  return a.doneOrder < b.doneOrder
            case (false, false): return a.order < b.order
            }
        }
    }

    var totalSets: Int { exercises.reduce(0) { $0 + $1.sets.count } }
    var completedSets: Int { exercises.reduce(0) { $0 + $1.sets.filter(\.done).count } }
    var isComplete: Bool { totalSets > 0 && completedSets == totalSets }
}

@Model
final class SessionExercise {
    var id: UUID = UUID()
    var exId: String = ""
    var order: Int = 0
    /// Monotonic counter set when the exercise becomes fully done (drives reorder). -1 = not done.
    var doneOrder: Int = -1
    /// Rest between sets for this exercise, in seconds. `nil` = use the app default.
    /// Copied from the plan's `PlanItem.restSeconds` when the session is built.
    var restSeconds: Int?
    var session: ActiveSession?

    @Relationship(deleteRule: .cascade, inverse: \LoggedSet.exercise)
    var sets: [LoggedSet] = []

    init(exId: String, order: Int = 0) {
        self.exId = exId
        self.order = order
    }

    var orderedSets: [LoggedSet] { sets.sorted { $0.order < $1.order } }
    var isDone: Bool { !sets.isEmpty && sets.allSatisfy(\.done) }

    /// The heaviest set by estimated 1RM (used for history & "best").
    var topSet: LoggedSet? {
        sets.max { Formulas.e1rm(kg: $0.weightKg, reps: $0.reps) < Formulas.e1rm(kg: $1.weightKg, reps: $1.reps) }
    }
}

@Model
final class LoggedSet {
    var id: UUID = UUID()
    var weightKg: Double = 20
    var reps: Int = 10
    var rpe: Int = 8
    var done: Bool = false
    /// Same set index's weight/reps from the previous session (drives trend arrows).
    var prevWeight: Double?
    var prevReps: Int?
    var order: Int = 0
    var exercise: SessionExercise?

    init(weightKg: Double, reps: Int, rpe: Int, prevWeight: Double? = nil, prevReps: Int? = nil, order: Int = 0) {
        self.weightKg = weightKg
        self.reps = reps
        self.rpe = rpe
        self.prevWeight = prevWeight
        self.prevReps = prevReps
        self.order = order
    }

    var weightTrend: Trend { TrendCalculator.trend(current: weightKg, previous: prevWeight) }
    var repsTrend: Trend { TrendCalculator.trend(current: Double(reps), previous: prevReps.map(Double.init)) }
}

//
//  PersistenceTests.swift
//  ReplogTests
//
//  SwiftData behavior against an in-memory container: building the onion,
//  cascade deletes, ordering, singletons, and generated-plan materialization.
//

import Testing
import Foundation
import SwiftData
@testable import Replog

@MainActor
struct PersistenceTests {

    private func makeContext() -> ModelContext {
        ModelContext(ReplogSchema.inMemoryContainer())
    }

    @Test func buildsPlanWorkoutItemSetHierarchy() throws {
        let ctx = makeContext()
        let plan = Plan(name: "PPL", order: 0)
        ctx.insert(plan)
        let workout = Workout(name: "Push Day", day: .mon, order: 0)
        workout.plan = plan
        ctx.insert(workout)
        let item = PlanItem(exId: "Barbell_Bench_Press", order: 0)
        item.workout = workout
        ctx.insert(item)
        for i in 0..<3 {
            let s = SetTemplate(weightKg: 60, reps: 10, rpe: 8, order: i)
            s.item = item
            ctx.insert(s)
        }
        try ctx.save()

        #expect(plan.workouts.count == 1)
        #expect(plan.exerciseCount == 1)
        #expect(workout.setCount == 3)
        #expect(plan.orderedWorkouts.first?.name == "Push Day")
    }

    @Test func cascadeDeleteRemovesSubtree() throws {
        let ctx = makeContext()
        let plan = Plan(name: "Temp", order: 0)
        ctx.insert(plan)
        let workout = Workout(name: "Day", day: .tue, order: 0)
        workout.plan = plan
        ctx.insert(workout)
        let item = PlanItem(exId: "X", order: 0)
        item.workout = workout
        ctx.insert(item)
        let set = SetTemplate(weightKg: 40, reps: 8, rpe: 7, order: 0)
        set.item = item
        ctx.insert(set)
        try ctx.save()

        ctx.delete(plan)
        try ctx.save()

        #expect(try ctx.fetch(FetchDescriptor<Plan>()).isEmpty)
        #expect(try ctx.fetch(FetchDescriptor<Workout>()).isEmpty)
        #expect(try ctx.fetch(FetchDescriptor<PlanItem>()).isEmpty)
        #expect(try ctx.fetch(FetchDescriptor<SetTemplate>()).isEmpty)
    }

    @Test func renamePersists() throws {
        let ctx = makeContext()
        let plan = Plan(name: "Old", order: 0)
        ctx.insert(plan)
        try ctx.save()
        plan.name = "New"
        try ctx.save()

        let fetched = try ctx.fetch(FetchDescriptor<Plan>())
        #expect(fetched.first?.name == "New")
    }

    @Test func orderedWorkoutsRespectOrderField() {
        let ctx = makeContext()
        let plan = Plan(name: "P", order: 0)
        ctx.insert(plan)
        for (i, day) in [Weekday.fri, .mon, .wed].enumerated() {
            let w = Workout(name: day.short, day: day, order: 2 - i) // reversed order field
            w.plan = plan
            ctx.insert(w)
        }
        // order fields: Fri=2, Mon=1, Wed=0 -> ordered should be Wed, Mon, Fri.
        #expect(plan.orderedWorkouts.map(\.day) == [.wed, .mon, .fri])
    }

    @Test func userProfileAndSettingsAreSingletons() {
        let ctx = makeContext()
        let p1 = ctx.userProfile()
        let p2 = ctx.userProfile()
        #expect(p1.id == p2.id)

        let s1 = ctx.appSettings()
        s1.units = .lb
        let s2 = ctx.appSettings()
        #expect(s2.units == .lb)
    }

    @Test func historyFetchFiltersAndSortsByDate() throws {
        let ctx = makeContext()
        let now = Date()
        let older = HistoryEntry(exId: "A", date: now.addingTimeInterval(-1000), topW: 50, topR: 5, e1rm: 58, sets: [])
        let newer = HistoryEntry(exId: "A", date: now, topW: 60, topR: 5, e1rm: 70, sets: [])
        let other = HistoryEntry(exId: "B", date: now, topW: 40, topR: 5, e1rm: 46, sets: [])
        [older, newer, other].forEach { ctx.insert($0) }
        try ctx.save()

        let a = ctx.history(forExercise: "A")
        #expect(a.count == 2)
        #expect(a.map(\.e1rm) == [58, 70]) // sorted oldest -> newest
    }

    @Test func recordedSetsRoundTripThroughJSON() {
        let entry = HistoryEntry(exId: "A", date: Date(), topW: 90, topR: 8, e1rm: 114,
                                 sets: [RecordedSet(w: 90, r: 8), RecordedSet(w: 80, r: 10)])
        #expect(entry.sets.count == 2)
        #expect(entry.sets.first == RecordedSet(w: 90, r: 8))
    }

    @Test func materializesGeneratedPlan() throws {
        let ctx = makeContext()
        let generator = PlanGenerator(catalog: ExerciseCatalog(bundle: .main))
        var answers = QuizAnswers(); answers.daysPerWeek = 3
        let generated = generator.generate(answers)

        PlanFactory.insert(generated, into: ctx, order: 0)
        try ctx.save()

        let plans = try ctx.fetch(FetchDescriptor<Plan>())
        #expect(plans.count == 1)
        #expect(plans.first?.workouts.count == 3)
        #expect((plans.first?.exerciseCount ?? 0) > 0)
        // Every materialized item has at least one set.
        let items = try ctx.fetch(FetchDescriptor<PlanItem>())
        #expect(items.allSatisfy { !$0.sets.isEmpty })
    }

    @Test func addWorkoutPicksFreeWeekday() throws {
        let ctx = makeContext()
        let plan = Plan(name: "P", order: 0)
        ctx.insert(plan)
        let mon = Workout(name: "A", day: .mon, order: 0); mon.plan = plan; ctx.insert(mon)
        let wed = Workout(name: "B", day: .wed, order: 1); wed.plan = plan; ctx.insert(wed)

        let added = PlanFactory.addWorkout(to: plan, into: ctx)
        // Mon & Wed taken; next preferred free day is Fri.
        #expect(added.day == .fri)
    }
}

//
//  UserData.swift
//  Replog
//
//  SwiftData models for the core "onion": Plan -> Workout -> PlanItem -> SetTemplate.
//  Cascade delete rules mean removing a plan removes its whole subtree.
//

import Foundation
import SwiftData

@Model
final class Plan {
    var id: UUID = UUID()
    var name: String = ""
    /// Accent dot color for the plan (hex). Cycles through a small palette by default.
    var colorHex: String = "#FF6A3D"
    var order: Int = 0
    var createdAt: Date = Date()
    /// The AI coach's saved report explaining the science behind this plan (markdown).
    /// Empty for manually-built plans. Re-readable from the Profile tab.
    var reportMarkdown: String = ""
    /// Display headline from generation, e.g. "Your Hypertrophy Plan".
    var headline: String = ""

    @Relationship(deleteRule: .cascade, inverse: \Workout.plan)
    var workouts: [Workout] = []

    init(name: String, colorHex: String = "#FF6A3D", order: Int = 0) {
        self.name = name
        self.colorHex = colorHex
        self.order = order
        self.createdAt = Date()
    }

    /// Whether this plan has a saved AI coach report.
    var hasReport: Bool { !reportMarkdown.isEmpty }

    /// Workouts in display order.
    var orderedWorkouts: [Workout] { workouts.sorted { $0.order < $1.order } }

    /// Total prescribed exercises across all workouts.
    var exerciseCount: Int { workouts.reduce(0) { $0 + $1.items.count } }

    /// Distinct scheduled weekdays, in week order.
    var scheduledDays: [Weekday] {
        let days = Set(workouts.map(\.day))
        return Weekday.allCases.filter { days.contains($0) }
    }
}

@Model
final class Workout {
    var id: UUID = UUID()
    var name: String = ""
    /// Stored as `Weekday.rawValue`; use `day` for typed access.
    var dayRaw: String = Weekday.mon.rawValue
    var order: Int = 0
    var plan: Plan?

    @Relationship(deleteRule: .cascade, inverse: \PlanItem.workout)
    var items: [PlanItem] = []

    init(name: String, day: Weekday, order: Int = 0) {
        self.name = name
        self.dayRaw = day.rawValue
        self.order = order
    }

    var day: Weekday {
        get { Weekday(rawValue: dayRaw) ?? .mon }
        set { dayRaw = newValue.rawValue }
    }

    var orderedItems: [PlanItem] { items.sorted { $0.order < $1.order } }
    var setCount: Int { items.reduce(0) { $0 + $1.sets.count } }
}

@Model
final class PlanItem {
    var id: UUID = UUID()
    /// References `Exercise.id` in the static catalog.
    var exId: String = ""
    var order: Int = 0
    /// Rest between sets for this exercise, in seconds. `nil` = use the app default.
    var restSeconds: Int?
    var workout: Workout?

    @Relationship(deleteRule: .cascade, inverse: \SetTemplate.item)
    var sets: [SetTemplate] = []

    init(exId: String, order: Int = 0) {
        self.exId = exId
        self.order = order
    }

    var orderedSets: [SetTemplate] { sets.sorted { $0.order < $1.order } }
}

@Model
final class SetTemplate {
    var id: UUID = UUID()
    var weightKg: Double = 20
    var reps: Int = 10
    var rpe: Int = 8
    var order: Int = 0
    var item: PlanItem?

    init(weightKg: Double, reps: Int, rpe: Int, order: Int = 0) {
        self.weightKg = weightKg
        self.reps = reps
        self.rpe = rpe
        self.order = order
    }
}

